import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { mkdtemp, readFile, readdir, rm } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { generateIcons, ICON_SIZES } from '../../scripts/icons.mjs';

// E0-F6: icons are generated by scripts/icons.mjs; src/icons must match its output byte for byte.
const SRC_ICONS = fileURLToPath(new URL('../../src/icons/', import.meta.url));
const sha256 = (buf) => createHash('sha256').update(buf).digest('hex');

async function hashes(dir) {
  const out = {};
  for (const name of (await readdir(dir)).filter((n) => n.endsWith('.png')).sort()) {
    out[name] = sha256(await readFile(join(dir, name)));
  }
  return out;
}

let dirA;
let dirB;
beforeAll(async () => {
  dirA = await mkdtemp(join(tmpdir(), 'pds-icons-a-'));
  dirB = await mkdtemp(join(tmpdir(), 'pds-icons-b-'));
  await generateIcons({ outDir: dirA });
  await generateIcons({ outDir: dirB });
});
afterAll(async () => {
  await rm(dirA, { recursive: true, force: true });
  await rm(dirB, { recursive: true, force: true });
});

describe('scripts/icons.mjs', () => {
  it('writes icon16/48/128.png with matching IHDR sizes (RGBA, 8 bit)', async () => {
    expect(ICON_SIZES).toEqual([16, 48, 128]);
    expect((await readdir(dirA)).sort()).toEqual(['icon128.png', 'icon16.png', 'icon48.png']);
    for (const size of ICON_SIZES) {
      const buf = await readFile(join(dirA, `icon${size}.png`));
      expect(buf.toString('ascii', 12, 16)).toBe('IHDR');
      expect([buf.readUInt32BE(16), buf.readUInt32BE(20)]).toEqual([size, size]);
      expect([buf[24], buf[25]]).toEqual([8, 6]);
    }
  });

  it('is deterministic (two runs give identical SHA-256)', async () => {
    expect(await hashes(dirB)).toEqual(await hashes(dirA));
  });

  it('src/icons is exactly the script output (no hand edits)', async () => {
    expect(await hashes(SRC_ICONS)).toEqual(await hashes(dirA));
  });
});
